    private record PursuitRead(long elapsed,int lane,Vec3 position,Vec3 velocity,Vec3 targetPosition,BlockPos pathTarget,BlockPos pathEnd,Vec3 nextNodeCenter,boolean grounded,boolean running,boolean pathMatches,boolean targetExact,boolean noAI,double predatory,double aggregate,double attribute){}
    /** First common admission from three already-completed natural END samples; never selects by a future ratio or retries a failed measurement. */
    private static void requirePursuitAdmission(GameTestHelper h,PursuitProbe probe,List<Trace> traces){
        long last=probe.latestSettling();h.assertTrue(last>=2,"three completed natural samples before first steady-state admission");
        for(int lane=0;lane<probe.sources.size();lane++){var source=probe.sources.get(lane);var target=probe.targets.get(lane);var newest=probe.settledAt(lane,last);h.assertTrue(newest!=null&&newest.nextNodeCenter!=null,"all three actors sampled with real next nodes at the same completed END");float width=source.getBbWidth()+source.getBonusMeleeRange(),targetWidth=target.getBbWidth()+target.getBonusMeleeRangeForAttackers();double reach=width*2f*width*2f+targetWidth;
            h.assertTrue(traces.get(lane).incoming.isEmpty()&&traces.get(lane).hits.isEmpty(),"natural settling cannot borrow a window after an actual melee hit");
            for(long tick=last-2;tick<=last;tick++){var read=probe.settledAt(lane,tick);h.assertTrue(read!=null&&read.grounded&&read.running&&read.pathMatches&&read.targetExact&&!read.noAI&&read.nextNodeCenter!=null,"past natural grounded running goal/current exact target/path sample: lane="+lane+" "+read);h.assertTrue(read.position.distanceToSqr(read.targetPosition)>reach&&read.targetPosition.x>read.position.x&&read.velocity.x>0,"past sample remains an actual forward chase outside native melee reach");h.assertTrue(Math.abs(read.position.z-read.nextNodeCenter.z)<.002&&Math.abs(read.velocity.z)<.0005&&Math.abs(read.nextNodeCenter.z-newest.nextNodeCenter.z)<1.0e-9&&Math.abs(read.velocity.x-newest.velocity.x)<.0005,"past three samples have naturally converged to one actual current node row with stable forward speed: lane="+lane+" "+read);}
        }
    }
    /** Pure Level END sampling: no navigation request, movement setter, or skill refresh call. */
    private static final class PursuitProbe{
        final GameTestHelper h;final List<TerrorbeakUnit> sources;final List<ShadowGhostUnit> targets;final List<PursuitRead> values=new ArrayList<>(),settling=new ArrayList<>();long chaseStart=-1,start=-1;PursuitProbe(GameTestHelper h,List<TerrorbeakUnit> sources,List<ShadowGhostUnit> targets){this.h=h;this.sources=sources;this.targets=targets;}
        long latestSettling(){return settling.stream().mapToLong(read->read.elapsed).max().orElse(-1);}
        PursuitRead settledAt(int lane,long elapsed){return settling.stream().filter(read->read.lane==lane&&read.elapsed==elapsed).findFirst().orElse(null);}
        PursuitRead at(int lane,long elapsed){return values.stream().filter(read->read.lane==lane&&read.elapsed==elapsed).findFirst().orElse(null);}
        @SubscribeEvent(priority=EventPriority.LOWEST) public void end(TickEvent.LevelTickEvent event){if(event.level!=h.getLevel()||event.phase!=TickEvent.Phase.END||chaseStart<0)return;for(int i=0;i<sources.size();i++){var source=sources.get(i);var path=source.getNavigation().getPath();(start<0?settling:values).add(new PursuitRead(event.level.getGameTime()-(start<0?chaseStart:start),i,source.position(),source.getDeltaMovement(),targets.get(i).position(),path==null?null:path.getTarget(),path==null||path.getEndNode()==null?null:path.getEndNode().asBlockPos(),path==null||path.isDone()?null:path.getNextEntityPos(source),actualFloor(h,source),source.goalSelector.getRunningGoals().anyMatch(goal->goal.getGoal()==source.getAttackGoal()),path!=null&&!source.getNavigation().isDone()&&path.getTarget().equals(targets.get(i).blockPosition()),source.getTarget()==targets.get(i),source.isNoAi(),TerrorbeakDreadRoar.predatoryBonus(source),SkillEffects.bonus(source,BuffKind.MOVEMENT_SPEED),source.getAttributeValue(Attributes.MOVEMENT_SPEED)));}}
    }
    private static int serializedModifiers(net.minecraft.nbt.CompoundTag nbt,UUID uuid){int count=0;var attributes=nbt.getList("Attributes",10);for(int i=0;i<attributes.size();i++){var modifiers=attributes.getCompound(i).getList("Modifiers",10);for(int j=0;j<modifiers.size();j++){var modifier=modifiers.getCompound(j);if(modifier.hasUUID("UUID")&&modifier.getUUID("UUID").equals(uuid))count++;}}return count;}

    private static final List<Object> EXTRA_LISTENERS=new ArrayList<>();
    private static final List<com.solegendary.reignofnether.building.BuildingPlacement> BUILDINGS=new ArrayList<>();
    private static Object rawField(Object object,String name){for(Class<?> type=object.getClass();type!=null;type=type.getSuperclass())try{var field=type.getDeclaredField(name);field.setAccessible(true);return field.get(object);}catch(NoSuchFieldException ignored){}catch(ReflectiveOperationException failure){throw new RuntimeException("raw native field "+name,failure);}throw new IllegalStateException("no raw native field "+name);}
    private static int rawInt(Object object,String name){return ((Number)rawField(object,name)).intValue();}
    private static boolean actualFloor(GameTestHelper h,Mob body){return body.onGround()&&body.verticalCollision&&Math.abs(body.getBoundingBox().minY-(h.absolutePos(BlockPos.ZERO).getY()+1))<.001;}
